def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in t:
        next_count = counts.get(ch, 0) - 1
        if next_count < 0:
            return False
        counts[ch] = next_count
    return True

